// Package hybrid assembles the integrated entry: one chat model, shared by Agent turns and conversation turns.
package hybrid

import (
	"GopherAI/config"
	"GopherAI/entry"
	"context"
	"errors"
	"gorm.io/gorm"
	"net/http"
)

type Application struct {
	Agent   *entry.Application
	Handler http.Handler
}

func (a *Application) Close() error { return a.Agent.Close() }

// Assemble uses the exact database opened by the original V2 assembly.
//
// A conversation turn is generated by the learning Agent's chat model, the one
// this deployment configures, so there is no second client to build and no
// ordinary conversation service to assemble: the ordinary path was retired and
// its code removed.
func Assemble(ctx context.Context, settings *entry.Settings, deps entry.Dependencies) (*Application, error) {
	if deps.Infrastructure.OpenDatabase == nil {
		return nil, errors.New("hybrid: V2 infrastructure required")
	}
	var db *gorm.DB
	open := deps.Infrastructure.OpenDatabase
	deps.Infrastructure.OpenDatabase = func(ctx context.Context, c *config.Config) (*gorm.DB, error) {
		var err error
		db, err = open(ctx, c)
		return db, err
	}
	agent, err := entry.Assemble(ctx, settings, deps)
	if err != nil {
		return nil, err
	}
	app := &Application{Agent: agent}
	app.Handler = newHTTPHandler(db, agent)
	return app, nil
}
